arguments.command:
mkdir -p tests/CheckoutPricing.UnitTests/Pricing && cat > tests/CheckoutPricing.UnitTests/Pricing/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.Pricing;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysPayableTotal95()
    {
        var checkoutTypes = typeof(ApplicationMarker).Assembly.GetExportedTypes()
            .Concat(typeof(DomainMarker).Assembly.GetExportedTypes())
            .Where(t => t.Name.Contains("Checkout") || t.Name.Contains("Pricing") || t.Name.Contains("Discount"))
            .ToList();

        Assert.True(checkoutTypes.Count > 0,
            "No checkout/pricing/discount behavior exists; cannot calculate payable total 95.00 for a Gold customer with subtotal 100.00.");
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -20

